script:
(function () {
  'use strict';
  // Maximum home price from debt-to-income (DTI) limits.
  //   Housing budget H = min(front% * monthly income, back% * monthly income - other monthly debts).
  //   Monthly housing cost at price P with cash down D: loan L = max(0, P - D);
  //   cost(P) = PI(L) + P * tax% / 12 + P * insurance% / 12 + HOA + PMI,
  //   PI(L) = L * i / (1 - (1 + i)^-n), i = rate / 12; PMI = pmi% * L / 12 when L > 80% of P.
  //   cost(P) never decreases as P rises, so the largest P with cost(P) <= H is found by bisection.
  // Verified in Node (scratchpad tests/m5): with no taxes/insurance/PMI the result equals the
  //   closed form P = D + H * (1 - (1 + i)^-n) / i (e.g. $100,000 income, 28% front-end, 6.5%, 30 yrs,
  //   $60,000 down -> $2,333.33 budget -> $429,158.58 price); cost at the returned price equals the
  //   budget to the cent; the back-end limit binds when debts are high; a budget at or below zero
  //   shows $0; 0% rate works; no NaN/Infinity on blank or bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var PRESETS = { conventional: [28, 36], fha: [31, 43] };
  var SCENARIOS = [
    { name: 'Cautious', front: 25, back: 33 },
    { name: 'Conventional 28/36', front: 28, back: 36 },
    { name: 'FHA 31/43', front: 31, back: 43 },
    { name: 'Back-end 45% only', front: null, back: 45 },
    { name: 'Back-end 50% only', front: null, back: 50 }
  ];

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function pi(loan, i, n) {
    if (loan <= 0) return 0;
    if (i === 0) return loan / n;
    return loan * i / (1 - Math.pow(1 + i, -n));
  }

  function costAt(price, o) {
    var loan = Math.max(0, price - o.down);
    var pmi = loan > 0.8 * price ? o.pmi * loan / 12 : 0;
    var parts = { pi: pi(loan, o.i, o.n), tax: price * o.tax / 12, ins: price * o.ins / 12, pmi: pmi, hoa: o.hoa };
    parts.total = parts.pi + parts.tax + parts.ins + parts.pmi + parts.hoa;
    parts.loan = loan;
    return parts;
  }

  function maxPrice(budget, o) {
    if (!(budget > 0) || costAt(0, o).total > budget) return 0;
    var lo = 0, hi = 100000;
    while (costAt(hi, o).total <= budget && hi < 1e10) { lo = hi; hi *= 2; }
    for (var k = 0; k < 200 && hi - lo > 0.001; k++) {
      var mid = (lo + hi) / 2;
      if (costAt(mid, o).total <= budget) lo = mid; else hi = mid;
    }
    return lo;
  }

  function budgetFor(front, back, monthlyIncome, debts) {
    var b = back / 100 * monthlyIncome - debts;
    return front === null ? b : Math.min(front / 100 * monthlyIncome, b);
  }

  function pct(x) { return (x * 100).toFixed(1) + '%'; }

  function clearResults() {
    ['haPrice', 'haLoan', 'haPayment', 'haDownPct', 'haPI', 'haTaxM', 'haInsM', 'haPmiM', 'haHoaM',
     'haFrontUsed', 'haBackUsed', 'haBinding'].forEach(function (id) { setText(id, '–'); });
    el('haScenarios').innerHTML = '';
  }

  function syncPreset(e) {
    var t = e && e.target ? e.target.id : '';
    if (t === 'haPreset') {
      var p = PRESETS[el('haPreset').value];
      if (p) { el('haFront').value = String(p[0]); el('haBack').value = String(p[1]); }
    } else if (t === 'haFront' || t === 'haBack') {
      var f = read('haFront'), b = read('haBack'), match = 'custom';
      Object.keys(PRESETS).forEach(function (k) { if (PRESETS[k][0] === f && PRESETS[k][1] === b) match = k; });
      el('haPreset').value = match;
    }
  }

  function update(e) {
    syncPreset(e);
    var income = read('haIncome'), debts = read('haDebts', true), down = read('haDown', true),
        rate = read('haRate'), term = read('haTerm'), front = read('haFront'), back = read('haBack'),
        tax = read('haTax', true), ins = read('haIns', true), hoa = read('haHoa', true), pmi = read('haPmi', true);
    var error = el('haError'), msg = '';
    if (isNaN(income) || income <= 0) msg = 'Enter your gross annual household income.';
    else if (isNaN(debts) || debts < 0 || isNaN(down) || down < 0) msg = 'Monthly debts and the down payment cannot be negative.';
    else if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (isNaN(term) || term < 1 || term > 50 || term % 1 !== 0) msg = 'Enter a loan term of 1 to 50 whole years.';
    else if (isNaN(front) || isNaN(back) || front <= 0 || back <= 0 || front > 100 || back > 100) msg = 'Enter front-end and back-end ratios between 1% and 100%.';
    else if ([tax, ins, hoa, pmi].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Taxes, insurance, HOA dues and PMI cannot be negative.';
    else if (tax > 10 || ins > 5 || pmi > 5) msg = 'Enter property tax up to 10%, and insurance and PMI rates up to 5%.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var mi = income / 12;
    var o = { down: down, i: rate / 100 / 12, n: term * 12, tax: tax / 100, ins: ins / 100, hoa: hoa, pmi: pmi / 100 };
    var frontCap = front / 100 * mi, backCap = back / 100 * mi - debts;
    var budget = Math.min(frontCap, backCap);
    var price = maxPrice(budget, o);
    var c = costAt(price, o);

    setText('haPrice', money0.format(price));
    setText('haLoan', money0.format(c.loan));
    setText('haPayment', money.format(price > 0 ? c.total : 0));
    setText('haDownPct', price > 0 ? pct(Math.min(down, price) / price) : '–');
    setText('haPI', money.format(c.pi));
    setText('haTaxM', money.format(c.tax));
    setText('haInsM', money.format(c.ins));
    setText('haPmiM', money.format(c.pmi));
    setText('haHoaM', money.format(price > 0 ? c.hoa : 0));
    setText('haFrontUsed', price > 0 ? pct(c.total / mi) + ' (limit ' + front + '%)' : '–');
    setText('haBackUsed', price > 0 ? pct((c.total + debts) / mi) + ' (limit ' + back + '%)' : pct(debts / mi) + ' (limit ' + back + '%)');

    var note;
    if (budget <= 0) note = 'Your other monthly debts already use the whole back-end limit, so these ratios leave nothing for housing. Paying down debt or raising income changes this.';
    else if (price === 0) note = 'HOA dues alone exceed the housing budget these ratios allow.';
    else if (frontCap <= backCap) note = 'The front-end limit (' + front + '% of income for housing) sets your maximum. Your other debts are low enough not to matter.';
    else note = 'The back-end limit (' + back + '% of income for housing plus other debts) sets your maximum. Each $100 of monthly debt you pay off lets you spend $100 more on housing, up to the front-end limit.';
    if (price > 0 && c.pmi > 0) note += ' With ' + pct(down / price) + ' down, PMI is included.';
    else if (price > 0 && c.total < budget - 1 && costAt(price + 1, o).pmi > 0)
      note += ' At this price your down payment is exactly 20%. A higher price would add PMI and push the payment over the limit, so the payment shown is below your budget.';
    setText('haBinding', note);

    el('haScenarios').innerHTML = SCENARIOS.map(function (s) {
      var b = budgetFor(s.front, s.back, mi, debts), p = maxPrice(b, o);
      return '<tr><th scope="row">' + s.name + '</th><td>' + (s.front === null ? 'None' : s.front + '%') + '</td><td>' + s.back +
        '%</td><td>' + money.format(Math.max(0, b)) + '</td><td>' + money0.format(p) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('haForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
